const VL_or=(x,y,h,col=INK,fill='#FFFFFF')=>`<path d="M${x} ${y}Q${x+h*.42} ${y+h/2} ${x} ${y+h}Q${x+h*.75} ${y+h} ${x+h*1.1} ${y+h/2}Q${x+h*.75} ${y} ${x} ${y}Z" fill="${fill}" stroke="${col}" stroke-width="3"/>`;
const VL_inv=(x,y,s,col=INK)=>`<path d="M${x} ${y-s/2}L${x+s} ${y}L${x} ${y+s/2}Z" fill="#FFFFFF" stroke="${col}" stroke-width="3"/><circle cx="${x+s+6}" cy="${y}" r="6" fill="#FFFFFF" stroke="${col}" stroke-width="3"/>`;
const VL_mux=(x,y,w,h,col=INK,fill='#FFFFFF')=>`<path d="M${x} ${y}L${x+w} ${y+h*.2}L${x+w} ${y+h*.8}L${x} ${y+h}Z" fill="${fill}" stroke="${col}" stroke-width="3" stroke-linejoin="round"/>`;
/* waveforms: f(t) in {0,1} sampled into a square-wave polyline */
const VL_wave=(f,t0,t1,x0,x1,ylo,yhi,col,w=3.5,n=600)=>{const p=[];let prev=null;for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n,x=x0+(x1-x0)*i/n,v=f(t);const y=v?yhi:ylo;if(prev!==null&&y!==prev)p.push([x,prev]);p.push([x,y]);prev=y}return VL_pl(p,col,w)};
