 /* droop: V falls linearly at Ileak / C; the clock must return before the drop reaches dV */
 const V=t=>1-0.12*t, ty=v=>318-(v-0.4)*150;
 const droop=[];for(let i=0;i<=40;i++){const t=i*4/40;droop.push([60+t*80,ty(V(t))])}
 const tmax=(1-0.6)/0.12;           // time for the allowed drop of 0.4 (picture units)
 const tx=60+tmax*80;
 return `
${g('pop',tk(c,'i1'),VL_box(14,10,612,152)+VL_T(34,44,'1 · the bit sits as charge on C',{fs:24,fw:700})+VL_T(50,104,'D',{fs:24,fw:800,fill:BLU})+VL_L(76,96,120,96,INK,3)+VL_L(120,96,160,78,INK,3)+VL_L(166,96,220,96,INK,3)+`<circle cx="220" cy="96" r="7" fill="${ORG}"/>`+VL_T(140,132,'gate off',{fs:20,a:'middle',fill:'#5C6577'})+VL_L(220,96,220,112,INK,3)+VL_L(204,112,236,112,INK,3)+VL_L(204,122,236,122,INK,3)+VL_L(220,122,220,140,INK,3)+VL_T(250,128,'C',{fs:22,fw:800,fill:ORG})+VL_L(220,96,290,96,INK,3)+VL_inv(290,96,40)+VL_L(342,96,372,96,INK,3)+VL_T(384,104,'Q',{fs:24,fw:800})+VL_T(420,88,'no loop:',{fs:22,fw:700,fill:'#5C6577'})+VL_T(420,118,'charge only',{fs:22,fw:700,fill:ORG}))}
${g('pop',tk(c,'i2'),VL_box(14,182,612,152)+VL_T(34,214,'2 · leakage droops the node',{fs:24,fw:700})+VL_L(60,318,390,318,'#ADB5BD',2)+VL_L(60,318,60,226,'#ADB5BD',2)+VL_pl(droop,ORG,4)+VL_L(60,ty(0.6),400,ty(0.6),'#5C6577',2,'stroke-dasharray="6 6"')+VL_L(tx,ty(0.6),tx,318,'#5C6577',2,'stroke-dasharray="4 4"')+VL_T(48,ty(1)+8,'V',{fs:20,fw:700,a:'end',fill:'#5C6577'})+VL_T(430,252,`slope ${VL_sb('I','leak')} ÷ C`,{fs:22,fw:700,fill:ORG})+VL_T(430,284,'ΔV: allowed droop',{fs:20,fw:700,fill:'#5C6577'})+VL_T(430,316,`${VL_sb('f','min')} ≈ ${VL_sb('I','leak')} ÷ (CΔV)`,{fs:22,fw:800,fill:INK}))}
${g('pop',tk(c,'i3'),VL_box(14,354,612,152)+VL_T(34,386,'3 · a clocked inverter (C²MOS)',{fs:24,fw:700})+VL_L(110,400,110,500,INK,3)+[['p','D',410],['p','CLK′',432],['n','CLK',468],['n','D',490]].map(([t,gl,y])=>VL_box(92,y-9,36,18,{fill:t==='p'?'#FFF4E6':'#E7F5FF',st:t==='p'?ORG:BLU,sw:2,r:4})+VL_T(80,y+7,gl,{fs:18,fw:700,a:'end',fill:t==='p'?ORG:BLU})).join('')+VL_L(110,450,170,450,INK,3)+VL_T(178,458,'out',{fs:20,fw:700})+VL_T(250,424,'0-0 overlap: only pull-ups conduct',{fs:20,fw:700,fill:ORG})+VL_T(250,456,'1-1 overlap: only pull-downs',{fs:20,fw:700,fill:BLU})+VL_T(250,488,'so data cannot race through',{fs:20,fw:700,fill:GRN}))}
${g('pop',tk(c,'i4'),VL_box(14,526,612,154)+VL_T(34,558,'4 · TSPC: one clock wire',{fs:24,fw:700})+VL_T(40,616,'D',{fs:24,fw:800,fill:BLU})+VL_arrow(64,608,104,608)+VL_box(108,580,170,56,{fill:'#E3FAF1',st:ACC,sw:3,r:10})+VL_T(193,616,'neg. latch',{fs:22,fw:800,a:'middle'})+VL_arrow(278,608,318,608)+VL_box(322,580,170,56,{fill:'#E3FAF1',st:ACC,sw:3,r:10})+VL_T(407,616,'pos. latch',{fs:22,fw:800,a:'middle'})+VL_arrow(492,608,532,608)+VL_T(540,616,'Q',{fs:24,fw:800})+VL_pl([[193,636],[193,656],[407,656],[407,636]],BLU,3)+VL_L(300,656,300,672,BLU,3)+VL_T(316,674,'CLK only',{fs:20,fw:800,fill:BLU}))}`;
