/* worked example 2: the shift register, computed from the input bits */
function VL_shiftPic(c){
 const din=[1,0,1,1];let q=[0,0,0,0];const rows=[['start','–',q.slice()]];
 din.forEach((d,i)=>{q=[d,q[0],q[1],q[2]];rows.push([String(i+1),String(d),q.slice()])});
 const keys=['i2','i2','i3','i3'],X0=40,cw=[110,90,90,90,90,90];
 let s=g('pop',tk(c,'g'),VL_box(14,10,612,150)+VL_T(34,42,'start 0000;  Din = 1, 0, 1, 1',{fs:24,fw:700})+['Q₀','Q₁','Q₂','Q₃'].map((n,i)=>VL_box(110+i*124,64,84,54,{fill:'#FFFFFF',st:INK,sw:3,r:8})+VL_T(152+i*124,100,n,{fs:24,fw:800,a:'middle'})+(i<3?VL_arrow(194+i*124,91,234+i*124,91):'')).join('')+VL_T(40,100,'Din',{fs:22,fw:800,fill:BLU})+VL_arrow(80,91,110,91,BLU,3)+VL_T(320,146,'',{}));
 s+=g('pop',tk(c,'i1'),VL_T(320,148,'every edge: each bit moves one place right',{fs:20,fw:700,a:'middle',fill:ORG}));
 const hx=[X0+55,X0+150,X0+245,X0+335,X0+425,X0+515];
 s+=g('pop',tk(c,'i1'),['edge','Din','Q₀','Q₁','Q₂','Q₃'].map((h,i)=>VL_T(hx[i],206,h,{fs:22,fw:800,a:'middle',fill:'#5C6577'})).join('')+VL_L(30,220,610,220,'#ADB5BD',2));
 rows.forEach((r,j)=>{const y=262+j*62,cells=VL_T(hx[0],y,r[0],{fs:24,fw:700,a:'middle'})+VL_T(hx[1],y,r[1],{fs:24,fw:800,a:'middle',fill:BLU})+r[2].map((v,i)=>VL_box(hx[2+i]-24,y-34,48,46,{fill:v?'#FFF3BF':'#FFFFFF',st:v?ORG:'#ADB5BD',sw:2,r:8})+VL_T(hx[2+i],y-2,String(v),{fs:26,fw:800,a:'middle',fill:v?ORG:'#5C6577'})).join('');
  s+=g('pop',j===0?tk(c,'i1'):tk(c,keys[j-1])+(j===2||j===4?0.9:0),cells)});
 const last=rows[4][2],word=last.slice().reverse().join('');
 s+=g('pop',tk(c,'i4'),VL_box(40,586,560,86,{fill:'#D3F9D8',st:GRN,sw:3,r:12})+VL_T(320,640,`Q₃Q₂Q₁Q₀ = ${word}`,{fs:30,fw:800,a:'middle',fill:GRN}));
 return s;
}
/* trap 2: a gated D latch is level-sensitive. k=0 the wrong idea (Q only samples at edges), k=1 Q follows D through CLK = 1 */
function VL_latchPic(k){
 /* D: 0, rises at 0.5, falls at 1.4 (inside the first high phase), rises at 1.7, falls at 3.5 */
 const D=t=>(t>=0.5&&t<1.4)||(t>=1.7&&t<3.5)?1:0;
 const edgeQ=t=>{let q=0;for(let e=1;e<=t;e+=2)q=D(e-1e-9);return q};
 const lat=t=>{let q=0;const n=800;for(let i=0;i<=n;i++){const u=t*i/n;if(VL_clk(u))q=D(u)}return q};
 const Q=k?lat:edgeQ, col=k?GRN:TRED;
 const x0=110,x1=610,T0=0,T1=4.6;
 const shade=[1,3].map(e=>`<rect x="${(x0+(x1-x0)*e/T1).toFixed(1)}" y="14" width="${((x1-x0)/T1).toFixed(1)}" height="290" fill="${BLU}" fill-opacity=".08"/>`).join('');
 return shade+VL_T(90,62,'CLK',{fs:22,fw:800,a:'end',fill:'#5C6577'})+VL_wave(VL_clk,T0,T1,x0,x1,74,34,INK,3)+VL_T(90,152,'D',{fs:22,fw:800,a:'end',fill:BLU})+VL_wave(D,T0,T1,x0,x1,164,124,BLU,3.5)+VL_T(90,242,'Q',{fs:22,fw:800,a:'end',fill:col})+VL_wave(Q,T0,T1,x0,x1,254,214,col,4.5)+VL_T(360,298,k?'shaded CLK = 1: Q follows every change of D':'Q drawn changing only at the edges',{fs:22,fw:800,a:'middle',fill:col});
}
/* answer 1: Y5 = A·B′·C needs the inverted B */
function VL_q1Pic(c){
 return `
${g('pop',tk(c,'a1'),VL_T(40,128,'A',{fs:30,fw:800,fill:BLU})+VL_L(80,118,330,118,INK,3)+VL_T(40,208,'B',{fs:30,fw:800,fill:BLU})+VL_L(80,198,150,198,INK,3)+VL_T(40,288,'C',{fs:30,fw:800,fill:BLU})+VL_L(80,278,330,278,INK,3)+VL_L(330,118,330,170,INK,3)+VL_L(330,278,330,226,INK,3)+VL_L(330,170,360,170,INK,3)+VL_L(330,226,360,226,INK,3)+VL_and(360,138,120,INK,'#E3FAF1')+VL_arrow(480,198,540,198,GRN,4)+VL_T(550,208,'Y₅',{fs:30,fw:800,fill:GRN})+VL_T(420,330,'AND',{fs:24,fw:800,a:'middle',fill:'#5C6577'}))}
${g('pop',tk(c,'a2'),VL_inv(160,198,50,ORG)+VL_L(222,198,360,198,ORG,4)+VL_T(270,184,'B′',{fs:28,fw:800,a:'middle',fill:ORG})+VL_T(185,250,'inverter',{fs:22,fw:700,a:'middle',fill:ORG}))}
${g('pop',tk(c,'a3'),VL_box(60,380,500,80,{fill:'#D3F9D8',st:GRN,sw:3,r:12})+VL_T(310,432,'Y₅ = A·B′·C: high only for 101',{fs:28,fw:800,a:'middle',fill:GRN}))}`;
}
/* answer 3: 1100 vs 1011, the first differing bit from the MSB decides */
function VL_q3Pic(c){
 const A=[1,1,0,0],B=[1,0,1,1];
 const d=A.findIndex((v,i)=>v!==B[i]);   // = 1, i.e. bit 2
 const hlA=A.map((_,i)=>i===d?'#D3F9D8':(i>d?'#F1F3F5':'#FFFFFF')), hlB=B.map((_,i)=>i===d?'#D3F9D8':(i>d?'#F1F3F5':'#FFFFFF'));
 const fc=A.map((_,i)=>i>d?'#ADB5BD':INK);
 return `
${g('pop',tk(c,'a1'),['bit 3','bit 2','bit 1','bit 0'].map((t,i)=>VL_T(200+i*100,60,t,{fs:22,fw:700,a:'middle',fill:'#5C6577'})).join('')+VL_T(90,122,'A = 12',{fs:24,fw:800,a:'middle'})+VL_bits(160,84,A,{w:100,h:56,fs:30,hl:hlA.map((h,i)=>i>d?'#FFFFFF':h),fc:A.map(()=>INK)})+VL_T(90,202,'B = 11',{fs:24,fw:800,a:'middle'})+VL_bits(160,164,B,{w:100,h:56,fs:30,hl:hlB.map((h,i)=>i>d?'#FFFFFF':h),fc:B.map(()=>INK)})+VL_arrow(160,262,330,262,GRN,4)+VL_T(160,296,'from the MSB: bit 2 decides, A > B',{fs:24,fw:800,fill:GRN}))}
${g('pop',tk(c,'a2'),`<rect x="356" y="78" width="200" height="150" rx="10" fill="#F1F3F5" fill-opacity=".85" stroke="${ORG}" stroke-width="3" stroke-dasharray="8 6"/>`+VL_T(456,252,'bits 1, 0 favour B:',{fs:22,fw:700,a:'middle',fill:ORG})+VL_T(456,278,'they cannot override',{fs:22,fw:700,a:'middle',fill:ORG}))}
${g('pop',tk(c,'a3'),VL_box(40,330,540,120,{fill:'#FFF4E6',st:ORG,sw:3,r:12})+VL_T(310,374,'LSB first: bit 0 says B > A,',{fs:24,fw:800,a:'middle',fill:ORG})+VL_T(310,412,'then bit 2 must undo it: extra logic',{fs:24,fw:800,a:'middle',fill:ORG}))}`;
}

function EXTRA(R,ICON){
 /* hook: an elevator panel where code 101 lights only lamp 5; a latch holding the press */
 ICON.vlLift=(x,y)=>{let s=`<g transform="translate(${x-200} ${y-110})">`+VL_box(0,0,400,220,{fill:'#FFFFFF',st:BLU,sw:3,r:18})+VL_T(24,40,'code 101 in',{fs:24,fw:800,fill:BLU})+VL_bits(200,12,[1,0,1],{w:52,h:40,fs:24});
  for(let i=0;i<8;i++){const cx=60+(i%4)*92,cy=i<4?100:170,on=i===5;s+=`<circle cx="${cx}" cy="${cy}" r="24" fill="${on?YEL:'#F1F3F5'}" stroke="${on?ORG:'#ADB5BD'}" stroke-width="3"/>`+VL_T(cx,cy+9,String(i),{fs:24,fw:800,a:'middle',fill:on?INK:'#868E96'})}
  return s+'</g>'};
 ICON.vlHold=(x,y)=>`<g transform="translate(${x-200} ${y-80})">${VL_box(0,0,400,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${VL_T(24,38,'a latch holds the press',{fs:24,fw:800,fill:ORG})}${VL_wave(VL_clk,0,5,30,370,128,96,INK,3)}${VL_T(30,82,'Q = 1, held',{fs:24,fw:800,fill:GRN})}${VL_L(190,74,370,74,GRN,5)}</g>`;
 /* recap pictures (about 420 x 330) */
 ICON.vlDec=(x,y)=>{let s=`<g transform="translate(${x-210} ${y-165})">`+VL_box(10,40,120,250,{fill:'#FFFFFF',st:BLU,sw:4,r:12})+VL_T(70,160,'3-to-8',{fs:24,fw:800,a:'middle'});
  for(let i=0;i<8;i++){const yy=62+i*29,on=[1,2,5,7].includes(i);s+=VL_L(130,yy,on?250:170,yy,on?BLU:'#ADB5BD',3)+(on?VL_L(250,yy,250,165,BLU,3):'')}
  return s+VL_or(250,130,70,BLU,'#E7F5FF')+VL_arrow(327,165,380,165,BLU,4)+VL_T(390,174,'f',{fs:30,fw:800,fill:BLU})+VL_T(210,320,'f = Σm(1, 2, 5, 7)',{fs:24,fw:800,a:'middle',fill:BLU})+'</g>'};
 ICON.vlMS=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${VL_box(10,20,170,70,{fill:'#FFFFFF',st:ORG,sw:4,r:12})}${VL_T(95,64,'master',{fs:26,fw:800,a:'middle'})}${VL_arrow(180,55,236,55,INK,3)}${VL_box(240,20,170,70,{fill:'#FFF4E6',st:ORG,sw:4,r:12})}${VL_T(325,64,'slave',{fs:26,fw:800,a:'middle'})}${VL_T(0,170,'CLK',{fs:22,fw:800,fill:'#5C6577'})}${VL_wave(VL_clk,0,6,60,410,180,140,INK,3)}${VL_T(0,270,'Q',{fs:22,fw:800,fill:ORG})}${VL_wave(t=>t>=1&&t<5?1:0,0,6,60,410,280,240,ORG,4)}${[1,3,5].map(e=>VL_L(60+350*e/6,130,60+350*e/6,292,'#ADB5BD',2,'stroke-dasharray="4 4"')).join('')}</g>`;
 ICON.vlDyn=(x,y)=>{const p=[];for(let i=0;i<=30;i++){const t=i/30*3;p.push([150+t*80,80+t*28])}
  return `<g transform="translate(${x-210} ${y-165})">${VL_L(60,60,60,140,INK,4)}${VL_L(20,140,100,140,INK,4)}${VL_L(20,160,100,160,INK,4)}${VL_L(60,160,60,220,INK,4)}${VL_L(30,220,90,220,INK,4)}${VL_T(110,206,'C',{fs:28,fw:800,fill:GRN})}${`<circle cx="60" cy="60" r="10" fill="${GRN}"/>`}${VL_L(150,60,150,240,'#ADB5BD',2)}${VL_L(150,240,410,240,'#ADB5BD',2)}${VL_pl(p,GRN,5)}${VL_L(150,140,400,140,'#5C6577',2,'stroke-dasharray="6 6"')}${VL_T(280,180,'charge leaks',{fs:24,fw:800,a:'middle',fill:GRN})}${VL_T(210,300,'clock must keep running',{fs:24,fw:800,a:'middle',fill:GRN})}</g>`};
}
